html:
{% set ws = frappe.db.get_value("Institution Settings") or {} %}
{% set pc = None %}
{% if frappe.db.exists("Applicant Portal Config", "Applicant Portal Config") %}
{% set pc = frappe.get_doc("Applicant Portal Config", "Applicant Portal Config") %}
{% endif %}
{% set pace_app = None %}
{% if doc.pace_application and frappe.db.exists("PACE Application", doc.pace_application) %}
{% set pace_app = frappe.get_doc("PACE Application", doc.pace_application) %}
{% endif %}
{% set prog_title = frappe.db.get_value("PACE Programme", doc.program, "programme_name") if doc.program else "" %}
{% set pr_gateway = frappe.db.get_value("Payment Request", doc.payment_request, "payment_gateway") if doc.payment_request else "" %}

{# DYNAMIC CAMPUS RESOLUTION (NO HARDCODING) #}
{% set campus = None %}
{% if doc.campus %}
    {% set campus = frappe.get_doc("Campus", doc.campus) if frappe.db.exists("Campus", doc.campus) else None %}
{% endif %}
{% if not campus %}
    {% set campus_list = frappe.get_all("Campus", filters={"is_active": 1}, limit=1) %}
    {% if campus_list %}
        {% set campus = frappe.get_doc("Campus", campus_list[0].name) %}
    {% endif %}
{% endif %}

{# CAMPUS LOGO AND DETAILS #}
{% set logo_src = campus.logo if campus and campus.logo else "" %}
{% set inst_name = campus.campus_name if campus else ((pc.portal_title if pc else None) or ws.get("title") or _("Institution")) %}
{% set inst_addr = "" %}
{% if campus %}
    {% set inst_addr = (campus.address or "") + (", " + campus.city if campus.city else "") + (", " + campus.state if campus.state else "") %}
{% endif %}
{% if not inst_addr and pc %}
    {% set inst_addr = pc.footer_address or "" %}
{% endif %}
{% set inst_phone = campus.phone_number if campus else ((pc.footer_phone if pc else None) or "") %}

{% set pay_date_str = frappe.utils.format_datetime(doc.payment_date, "dd/MM/yyyy HH:mm") if doc.payment_date else "" %}
{% set gen_date_str = frappe.utils.format_datetime(doc.generated_on, "dd/MM/yyyy HH:mm") if doc.generated_on else "" %}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;0,900;1,300;1,400;1,700;1,900&display=swap');

    @media print {
        @page { size: auto; margin: 10mm; }
        .receipt-container { padding: 5mm; border: none; }
        .receipt-outer-border { border: 1.5px solid #000; padding: 15px; }
    }

    .receipt-container {
        font-family: 'Merriweather', Arial, Helvetica, sans-serif;
        color: #000;
        font-size: 13px;
        line-height: 1.4;
        width: 100%;
        max-width: 800px;
        margin: 0 auto;
        padding: 20px;
    }

    .receipt-outer-border {
        border: 1.5px solid #000;
        padding: 25px;
        min-height: 820px;
        display: flex;
        flex-direction: column;
    }

    .receipt-header {
        display: flex;
        justify-content: center;
        align-items: center;
        margin-bottom: 30px;
        position: relative;
        min-height: 120px;
    }

    .header-logo {
        position: absolute;
        left: 0;
        top: 0;
        width: 120px;
        height: 120px;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .header-logo img {
        max-width: 100%;
        max-height: 100%;
        object-fit: contain;
    }

    .header-info {
        text-align: center;
        width: 100%;
        padding: 0 130px;
    }

    .college-name {
        font-size: 21px;
        font-weight: bold;
        text-transform: uppercase;
        margin-bottom: 6px;
    }

    .college-address {
        font-size: 15px;
        font-weight: bold;
        color: #000;
        margin-bottom: 8px;
        line-height: 1.3;
    }

    .college-phone {
        font-size: 16px;
        font-weight: bold;
    }

    .title-bar {
        text-align: center;
        margin-bottom: 35px;
        font-size: 16px;
        font-weight: bold;
        text-transform: uppercase;
    }

    .receipt-meta {
        display: flex;
        justify-content: space-between;
        margin-bottom: 25px;
        font-weight: bold;
    }

    .info-grid {
        margin-bottom: 35px;
        padding-left: 60px;
    }

    .info-row {
        display: flex;
        margin-bottom: 6px;
    }

    .info-label {
        width: 180px;
        text-align: left;
    }

    .info-dots {
        width: 20px;
        text-align: center;
    }

    .info-value {
        font-weight: normal;
        flex: 1;
    }

    .particulars-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 5px;
    }

    .particulars-table th, .particulars-table td {
        border: 1px solid #ccc;
        padding: 8px 10px;
    }

    .particulars-table th {
        font-weight: bold;
        background: #fdfdfd;
    }

    .text-right { text-align: right !important; }
    .text-center { text-align: center !important; }

    .grand-total-row {
        background-color: #f9f9f9;
        font-weight: bold;
    }

    .receipt-footer {
        margin-top: 15px;
        font-size: 13px;
    }

    .amount-words {
        margin-bottom: 40px;
        font-weight: bold;
    }

    .receipt-note {
        margin-top: auto;
        padding-bottom: 20px;
    }

    .receipt-note strong {
        text-decoration: underline;
        font-style: italic;
    }

    .receipt-note ul {
        margin: 5px 0;
        padding-left: 20px;
        list-style-type: disc;
    }

    .receipt-note li {
        margin-bottom: 4px;
        font-style: italic;
        font-weight: bold;
    }

    .footer-disclaimer {
        border-top: 1.5px solid #000;
        padding-top: 8px;
        text-align: center;
        font-weight: bold;
        font-style: italic;
        font-size: 13.5px;
    }
</style>

<div class="receipt-container">
    <div class="receipt-outer-border">
        <div class="receipt-header">
            <div class="header-logo">
                {% if logo_src %}
                    <img src="{{ logo_src }}" alt="Logo">
                {% endif %}
            </div>
            <div class="header-info">
                <div class="college-name">{{ inst_name }}</div>
                {% if inst_addr %}
                <div class="college-address">{{ inst_addr }}</div>
                {% endif %}
                {% if inst_phone %}
                    <div class="college-phone">{{ _("Phone") }} : {{ inst_phone }}</div>
                {% endif %}
            </div>
        </div>

        <div class="title-bar">{{ _("PACE FEES RECEIPT") }}</div>

        <div class="receipt-meta">
            <div>{{ _("Receipt No") }} : {{ doc.name }}</div>
            <div>{{ _("Date") }} : {{ pay_date_str }}</div>
        </div>

        <div class="info-grid">
            <div class="info-row"><span class="info-label">{{ _("Name") }}</span><span class="info-dots">:</span><span class="info-value">{{ doc.applicant_name or "" }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Programme") }}</span><span class="info-dots">:</span><span class="info-value">{{ prog_title or doc.program or "" }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Application No") }}</span><span class="info-dots">:</span><span class="info-value">{{ doc.pace_application or "" }}</span></div>
            {% if pace_app and pace_app.academic_year %}
            <div class="info-row"><span class="info-label">{{ _("Academic Year") }}</span><span class="info-dots">:</span><span class="info-value">{{ pace_app.academic_year }}</span></div>
            {% endif %}
            <div class="info-row"><span class="info-label">{{ _("Fee Type") }}</span><span class="info-dots">:</span><span class="info-value">{{ doc.fee_type or "" }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Payment Mode") }}</span><span class="info-dots">:</span><span class="info-value">{{ pr_gateway or _("Online") }}</span></div>
            {% if doc.transaction_id %}
            <div class="info-row"><span class="info-label">{{ _("Transaction No") }}</span><span class="info-dots">:</span><span class="info-value">{{ doc.transaction_id }}</span></div>
            {% endif %}
            {% if gen_date_str %}
            <div class="info-row"><span class="info-label">{{ _("Receipt Generated On") }}</span><span class="info-dots">:</span><span class="info-value">{{ gen_date_str }}</span></div>
            {% endif %}
            {% if doc.currency %}
            <div class="info-row"><span class="info-label">{{ _("Currency") }}</span><span class="info-dots">:</span><span class="info-value">{{ doc.currency }}</span></div>
            {% endif %}
        </div>

        <table class="particulars-table">
            <thead>
                <tr>
                    <th style="width: 60px;" class="text-center">{{ _("S.No") }}</th>
                    <th>{{ _("Particulars") }}</th>
                    <th style="width: 160px;" class="text-right">{{ _("Amount") }} ({{ doc.currency or "INR" }})</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td class="text-center">1</td>
                    <td>
                        {% if pace_app and pace_app.academic_year %}{{ pace_app.academic_year }} — {% endif %}
                        {{ doc.fee_type or _("PACE Fee") }}
                        {% if prog_title %} — {{ prog_title }}{% elif doc.program %} — {{ doc.program }}{% endif %}
                    </td>
                    <td class="text-right">{{ doc.get_formatted("amount") }}</td>
                </tr>
                <tr class="grand-total-row">
                    <td colspan="2" class="text-right">{{ _("Gross Total") }}</td>
                    <td class="text-right">{{ doc.get_formatted("amount") }}</td>
                </tr>
                <tr class="grand-total-row">
                    <td colspan="2" class="text-right">{{ _("Net Paid Amount") }}</td>
                    <td class="text-right">{{ doc.get_formatted("amount") }}</td>
                </tr>
                <tr>
                    <td colspan="2" class="text-right">{{ _("Due Amount") }}</td>
                    <td class="text-right">0.00</td>
                </tr>
            </tbody>
        </table>

        <div class="receipt-footer">
            <div class="amount-words">
                ({{ _("Amount in words") }} : {{ frappe.utils.money_in_words(doc.amount, doc.currency or "INR") }})
            </div>
        </div>

        <div class="receipt-note">
            <strong>{{ _("Note") }}:</strong>
            <ul>
                <li>{{ _("Transaction fee charges are non-refundable and non-reversible under any circumstances.") }}</li>
                <li>{{ _("All transaction fees will be borne by the account/card holder.") }}</li>
            </ul>
        </div>

        <div class="footer-disclaimer">{{ _("This is a computer-generated receipt and no signature is required") }}</div>
    </div>
</div>
